			default:
				Error(node, null, Sizeof, Identifier, IntegerConstant, FloatingConstant, CharacterConstant, StringLiteral, Lparen, Inc, Dec, Amp, Star, Plus, Minus, Tilde, Bang);
				break;
		}
		Leave();
		return node;
	}

	// multiplicative_expression= cast_expression { ( "*" | "/" | "%" ) cast_expression }; (left recursion rewritten as a loop)
	ParseNode ParseMultiplicativeExpression(int returnState)
	{
		Enter(MultiplicativeExpression, returnState);
		var node = NewNode(MultiplicativeExpression);
		node.Add(ParseCastExpression(801));
		// { ( "*" | "/" | "%" ) cast_expression }
		while (Current.SymbolId is Star or Slash or Percent)
		{
			node = Fold(node);
			// "*" | "/" | "%"
			switch (Current.SymbolId)
			{
				case Star:
				case Slash:
				case Percent:
					Consume(node);
					break;
				default:
					Error(node, null, Star, Slash, Percent);
					break;
			}
			node.Add(ParseCastExpression(813));
		}
		Leave();
		return node;
	}

	// additive_expression= multiplicative_expression { ( "+" | "-" ) multiplicative_expression }; (left recursion rewritten as a loop)
	ParseNode ParseAdditiveExpression(int returnState)
	{
		Enter(AdditiveExpression, returnState);
		var node = NewNode(AdditiveExpression);
		node.Add(ParseMultiplicativeExpression(814));
		// { ( "+" | "-" ) multiplicative_expression }
		while (Current.SymbolId is Plus or Minus)
		{
			node = Fold(node);
			// "+" | "-"
			if (Current.SymbolId == Plus)
			{
				Consume(node);
			}
			else
			{
				Expect(Minus, node);
			}
			node.Add(ParseMultiplicativeExpression(824));
		}
		Leave();
		return node;
	}

	// shift_expression= additive_expression { ( "<<" | ">>" ) additive_expression }; (left recursion rewritten as a loop)
	ParseNode ParseShiftExpression(int returnState)
	{
		Enter(ShiftExpression, returnState);
		var node = NewNode(ShiftExpression);
		node.Add(ParseAdditiveExpression(825));
		// { ( "<<" | ">>" ) additive_expression }
		while (Current.SymbolId is Shl or Shr)
		{
			node = Fold(node);
			// "<<" | ">>"
			if (Current.SymbolId == Shl)
			{
				Consume(node);
			}
			else
			{
				Expect(Shr, node);
			}
			node.Add(ParseAdditiveExpression(835));
		}
		Leave();
		return node;
	}

	// relational_expression= shift_expression { ( "<" | ">" | "<=" | ">=" ) shift_expression }; (left recursion rewritten as a loop)
	ParseNode ParseRelationalExpression(int returnState)
	{
		Enter(RelationalExpression, returnState);
		var node = NewNode(RelationalExpression);
		node.Add(ParseShiftExpression(836));
		// { ( "<" | ">" | "<=" | ">=" ) shift_expression }
		while (Current.SymbolId is Lt or Gt or Le or Ge)
		{
			node = Fold(node);
			// "<" | ">" | "<=" | ">="
			switch (Current.SymbolId)
			{
				case Lt:
				case Gt:
				case Le:
				case Ge:
					Consume(node);
					break;
				default:
					Error(node, null, Lt, Gt, Le, Ge);
					break;
			}
			node.Add(ParseShiftExpression(850));
		}
		Leave();
		return node;
	}

	// equality_expression= relational_expression { ( "==" | "!=" ) relational_expression }; (left recursion rewritten as a loop)
	ParseNode ParseEqualityExpression(int returnState)
	{
		Enter(EqualityExpression, returnState);
		var node = NewNode(EqualityExpression);
		node.Add(ParseRelationalExpression(851));
		// { ( "==" | "!=" ) relational_expression }
		while (Current.SymbolId is EqEq or Ne)
		{
			node = Fold(node);
			// "==" | "!="
			if (Current.SymbolId == EqEq)
			{
				Consume(node);
			}
			else
			{
				Expect(Ne, node);
			}
			node.Add(ParseRelationalExpression(861));
		}
		Leave();
		return node;
	}

	// AND_expression= equality_expression { "&" equality_expression }; (left recursion rewritten as a loop)
	ParseNode ParseANDExpression(int returnState)
	{
		Enter(ANDExpression, returnState);
		var node = NewNode(ANDExpression);
		node.Add(ParseEqualityExpression(862));
		// { "&" equality_expression }
		while (Current.SymbolId == Amp)
		{
			node = Fold(node);
			Consume(node);
			node.Add(ParseEqualityExpression(867));
		}
		Leave();
		return node;
	}

	// exclusive_OR_expression= AND_expression { "^" AND_expression }; (left recursion rewritten as a loop)
	ParseNode ParseExclusiveORExpression(int returnState)
	{
		Enter(ExclusiveORExpression, returnState);
		var node = NewNode(ExclusiveORExpression);
		node.Add(ParseANDExpression(868));
		// { "^" AND_expression }
		while (Current.SymbolId == Caret)
		{
			node = Fold(node);
			Consume(node);
			node.Add(ParseANDExpression(873));
		}
		Leave();
		return node;
	}

	// inclusive_OR_expression= exclusive_OR_expression { "|" exclusive_OR_expression }; (left recursion rewritten as a loop)
	ParseNode ParseInclusiveORExpression(int returnState)
	{
		Enter(InclusiveORExpression, returnState);
		var node = NewNode(InclusiveORExpression);
		node.Add(ParseExclusiveORExpression(874));
		// { "|" exclusive_OR_expression }
		while (Current.SymbolId == Pipe)
		{
			node = Fold(node);
			Consume(node);
			node.Add(ParseExclusiveORExpression(879));
		}
		Leave();
		return node;
	}

	// logical_AND_expression= inclusive_OR_expression { "&&" inclusive_OR_expression }; (left recursion rewritten as a loop)
	ParseNode ParseLogicalANDExpression(int returnState)
	{
		Enter(LogicalANDExpression, returnState);
		var node = NewNode(LogicalANDExpression);
		node.Add(ParseInclusiveORExpression(880));
		// { "&&" inclusive_OR_expression }
		while (Current.SymbolId == AndAnd)
		{
			node = Fold(node);
			Consume(node);
			node.Add(ParseInclusiveORExpression(885));
		}
		Leave();
		return node;
	}

	// logical_OR_expression= logical_AND_expression { "||" logical_AND_expression }; (left recursion rewritten as a loop)
	ParseNode ParseLogicalORExpression(int returnState)
	{
		Enter(LogicalORExpression, returnState);
		var node = NewNode(LogicalORExpression);
		node.Add(ParseLogicalANDExpression(886));
		// { "||" logical_AND_expression }
		while (Current.SymbolId == OrOr)
		{
			node = Fold(node);
			Consume(node);
			node.Add(ParseLogicalANDExpression(891));
		}
		Leave();
		return node;
	}

	// conditional_expression= logical_OR_expression [ "?" expression ":" conditional_expression ];
	ParseNode ParseConditionalExpression(int returnState)
	{
		Enter(ConditionalExpression, returnState);
		var node = NewNode(ConditionalExpression);
		node.Add(ParseLogicalORExpression(892));
		// [ "?" expression ":" conditional_expression ]
		if (Current.SymbolId == Question)
		{
			Consume(node);
			node.Add(ParseExpression(897));
			Expect(Colon, node);
			node.Add(ParseConditionalExpression(899));
		}
		Leave();
		return node;
	}

	// assignment_expression= conditional_expression | unary_expression assignment_operator assignment_expression;
	ParseNode ParseAssignmentExpression(int returnState)
	{
		Enter(AssignmentExpression, returnState);
		var node = NewNode(AssignmentExpression);
		// no fixed lookahead decides this; ALL(*) looks as far as it has to
		switch (AdaptivePredict(13))
		{
			case 0:
				node.Add(ParseConditionalExpression(903));
				break;
			case 1:
				node.Add(ParseUnaryExpression(905));
				ParseAssignmentOperator(node, 906);
				node.Add(ParseAssignmentExpression(907));
				break;
			default:
				Error(node, null, Sizeof, Identifier, IntegerConstant, FloatingConstant, CharacterConstant, StringLiteral, Lparen, Inc, Dec, Amp, Star, Plus, Minus, Tilde, Bang);
				break;
		}
		Leave();
		return node;
	}

	// assignment_operator<collapsed>= "=" | "*=" | "/=" | "%=" | "+=" | "-=" | "<<=" | ">>=" | "&=" | "^=" | "|=";
	void ParseAssignmentOperator(ParseNode parent, int returnState)
	{
		Enter(AssignmentOperator, returnState);
		switch (Current.SymbolId)
		{
			case Assign:
			case MulAssign:
			case DivAssign:
			case ModAssign:
			case AddAssign:
			case SubAssign:
			case ShlAssign:
			case ShrAssign:
			case AndAssign:
			case XorAssign:
			case OrAssign:
				Consume(parent);
				break;
			default:
				Error(parent, null, Assign, MulAssign, DivAssign, ModAssign, AddAssign, SubAssign, ShlAssign, ShrAssign, AndAssign, XorAssign, OrAssign);
				break;
		}
		Leave();
	}

	// expression= assignment_expression { "," assignment_expression }; (left recursion rewritten as a loop)
	ParseNode ParseExpression(int returnState)
	{
		Enter(Expression, returnState);
		var node = NewNode(Expression);
		node.Add(ParseAssignmentExpression(932));
		// { "," assignment_expression }
		while (Current.SymbolId == Comma)
		{
			node = Fold(node);
			Consume(node);
			node.Add(ParseAssignmentExpression(937));
		}
		Leave();
		return node;
	}

	// constant_expression<collapsed>= conditional_expression;
	void ParseConstantExpression(ParseNode parent, int returnState)
	{
		Enter(ConstantExpression, returnState);
		parent.Add(ParseConditionalExpression(938));
		Leave();
	}

	// contextual terminals: what a token is depends on what has been parsed, so it's decided as the parser looks at it
	protected override int Classify(Token token, Token previous)
	{
		switch (token.SymbolId)
		{
			case Identifier:
				if (IsTypedefName(token, previous)) return TypedefName;
				break;
		}
		return token.SymbolId;
	}

	protected override void OnMatched(Token token)
	{
		switch (token.SymbolId)
		{
			case Typedef:
				OnTypedefKeyword(token);
				break;
		}
	}

